import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";

const cursorSchema = z.object({ created_at: z.iso.datetime({ offset: true }), id: z.uuid() });
export type HistoryMessage = { id: string; role: string; content: string; created_at: string };
export type HistoryThread = { id: string; title: string; created_at: string };
export const THREAD_PAGE = 30;
const MESSAGE_PAGE = 100;
export const conversationTitleSchema = z.string().trim().min(1).max(120);

function before(value?: string) {
  if (!value) return null;
  try { return cursorSchema.parse(JSON.parse(value)); } catch { throw new Error("Invalid history cursor"); }
}
function cursor(row: { id: string; created_at: string }) { return JSON.stringify(row && { id: row.id, created_at: row.created_at }); }
// ponytail: LIKE wildcards are escaped; PostgREST also treats * as %, so it becomes a one-character wildcard.
function likePattern(query: string) { return `%${query.replace(/[\\%_]/g, "\\$&").replaceAll("*", "_")}%`; }

/** Newest-first saved chats, keyset-paged; `query` searches titles and message text instead. */
export async function loadThreads(supabase: SupabaseClient, workspace: string, threadsBefore?: string, query?: string) {
  const live = () => supabase.from("conversations").select("id,title,created_at").eq("workspace_id", workspace).is("deleted_at", null);
  const q = query?.trim().slice(0, 100);
  if (q) {
    const pattern = likePattern(q);
    const [titles, hits] = await Promise.all([
      live().ilike("title", pattern).order("created_at", { ascending: false }).limit(THREAD_PAGE),
      supabase.from("messages").select("conversation_id").eq("workspace_id", workspace).ilike("content", pattern).order("created_at", { ascending: false }).limit(200),
    ]);
    if (titles.error || hits.error) throw new Error("Could not search conversations. Try again.");
    const known = new Set((titles.data ?? []).map(row => row.id));
    const extra = [...new Set((hits.data ?? []).map(row => row.conversation_id as string))].filter(id => !known.has(id)).slice(0, THREAD_PAGE);
    const matched = extra.length ? await live().in("id", extra) : { data: [], error: null };
    if (matched.error) throw new Error("Could not search conversations. Try again.");
    const threads = [...(titles.data ?? []), ...(matched.data ?? [])]
      .sort((a, b) => b.created_at.localeCompare(a.created_at)).slice(0, THREAD_PAGE) as HistoryThread[];
    return { threads, threadsCursor: null };
  }
  const tc = before(threadsBefore);
  let tq = live().order("created_at", { ascending: false }).order("id", { ascending: false });
  if (tc) tq = tq.or(`created_at.lt.${tc.created_at},and(created_at.eq.${tc.created_at},id.lt.${tc.id})`);
  const { data, error } = await tq.limit(THREAD_PAGE + 1);
  if (error) throw new Error("Could not load conversations. Try again.");
  const threads = (data ?? []).slice(0, THREAD_PAGE) as HistoryThread[];
  return { threads, threadsCursor: (data?.length ?? 0) > THREAD_PAGE ? cursor(threads[threads.length - 1]) : null };
}

/** One owned conversation and a newest page of its messages (oldest first), loaded in parallel. */
export async function loadConversation(supabase: SupabaseClient, workspace: string, id: string, messagesBefore?: string) {
  const mc = before(messagesBefore);
  if (!z.uuid().safeParse(id).success) throw new Error("Conversation unavailable");
  let mq = supabase.from("messages").select("id,role,content,created_at").eq("workspace_id", workspace).eq("conversation_id", id).order("created_at", { ascending: false }).order("id", { ascending: false });
  if (mc) mq = mq.or(`created_at.lt.${mc.created_at},and(created_at.eq.${mc.created_at},id.lt.${mc.id})`);
  const [conversation, page] = await Promise.all([
    supabase.from("conversations").select("id,title,created_at").eq("workspace_id", workspace).eq("id", id).is("deleted_at", null).maybeSingle(),
    mq.limit(MESSAGE_PAGE + 1),
  ]);
  if (conversation.error) throw new Error("Could not load conversation. Try again.");
  if (!conversation.data) throw new Error("Conversation unavailable. It may be missing or belong to another workspace.");
  if (page.error) throw new Error("Could not load messages. Try again.");
  const messages = (page.data ?? []).slice(0, MESSAGE_PAGE) as HistoryMessage[];
  const messagesCursor = (page.data?.length ?? 0) > MESSAGE_PAGE ? cursor(messages[messages.length - 1]) : null;
  return { selected: conversation.data as HistoryThread, messages: messages.reverse(), messagesCursor };
}

export async function loadConversationHistory(supabase: SupabaseClient, workspace: string, requested?: string, threadsBefore?: string, messagesBefore?: string) {
  before(messagesBefore);
  if (requested && requested !== "new" && !z.uuid().safeParse(requested).success) throw new Error("Conversation unavailable");
  const explicit = requested && requested !== "new" ? loadConversation(supabase, workspace, requested, messagesBefore) : null;
  explicit?.catch(() => {});
  const { threads, threadsCursor } = await loadThreads(supabase, workspace, threadsBefore);
  const fallback = !requested && threads[0] ? loadConversation(supabase, workspace, threads[0].id, messagesBefore) : null;
  const conversation = await (explicit ?? fallback);
  return { threads, threadsCursor, selected: conversation?.selected ?? null, messages: conversation?.messages ?? [], messagesCursor: conversation?.messagesCursor ?? null };
}
"use client";

import { useRef, useState } from "react";
import type { FollowUp } from "./follow-ups";

export type ChatAnswer = { answer: string; conversationId: string; toolsUsed?: string[]; followUps?: FollowUp[] };
export type ChatStreamEvent =
  | { type: "started" }
  | { type: "tool"; id?: string; name: string; state: "running" | "done" | "failed" }
  | { type: "plan"; steps: string[] }
  | ({ type: "answer" } & ChatAnswer)
  | { type: "result"; status: number; body: unknown };

/** Reads the opt-in NDJSON stream, or a plain JSON response, into the final status and body. */
async function readResponse(response: Response, onEvent: (event: ChatStreamEvent) => void): Promise<{ ok: boolean; body: { error?: string } & Partial<ChatAnswer> }> {
  if (!response.headers.get("content-type")?.includes("application/x-ndjson") || !response.body) return { ok: response.ok, body: await response.json() };
  const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = "";
  for (;;) {
    const { value, done } = await reader.read();
    buffer += value ?? "";
    const lines = buffer.split("\n");
    buffer = done ? "" : lines.pop()!;
    for (const line of lines.filter(Boolean)) {
      const event = JSON.parse(line) as ChatStreamEvent;
      if (event.type === "result") return { ok: event.status < 400, body: event.body as { error?: string } };
      onEvent(event);
    }
    if (done) throw new Error("The answer stream ended early; reload to see whether it was saved");
  }
}

export function useChatRequest() {
  const active = useRef<{ requestId: string; controller: AbortController } | null>(null);
  const [status, setStatus] = useState<"idle" | "running" | "completed" | "failed" | "canceled">("idle");
  const [error, setError] = useState("");

  async function send(payload: { conversationId: string; message: string; context?: Record<string, unknown> }, onEvent?: (event: ChatStreamEvent) => void) {
    if (active.current) return null;
    const run = { requestId: crypto.randomUUID(), controller: new AbortController() };
    active.current = run;
    setStatus("running");
    setError("");
    try {
      const response = await fetch("/api/chat", { method: "POST", headers: { "Content-Type": "application/json", Accept: "application/x-ndjson, application/json" },
        signal: run.controller.signal, body: JSON.stringify({ ...payload, requestId: run.requestId }) });
      // Events from a canceled run are never shown.
      const result = await readResponse(response, event => { if (active.current === run) onEvent?.(event); });
      if (active.current !== run) return null;
      if (!result.ok) throw new Error(result.body.error ?? "Could not answer");
      setStatus("completed");
      return result.body as ChatAnswer;
    } catch (cause) {
      if (active.current === run) { setStatus("failed"); setError(cause instanceof Error ? cause.message : "Could not answer"); }
      return null;
    } finally { if (active.current === run) active.current = null; }
  }

  async function cancel() {
    const run = active.current;
    if (!run) return;
    try {
      let response: Response | undefined;
      // Cancellation can arrive before the server has claimed this request.
      for (let attempt = 0; attempt < 10; attempt++) {
        response = await fetch("/api/chat", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ requestId: run.requestId }) });
        if (response.status !== 404) break;
        await new Promise(resolve => setTimeout(resolve, 100));
      }
      const result = await response!.json();
      if (!response!.ok) throw new Error(result.error ?? "Could not cancel; try again");
      if (result.status === "canceled" && active.current === run) {
        active.current = null;
        run.controller.abort();
        setStatus("canceled");
      }
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not cancel; try again"); }
  }

  return { send, cancel, status, error, busy: status === "running" };
}
import { z } from "zod";
import type { EvidenceReceipt } from "@/lib/finance/evidence-receipts";

/** App-written chart block. The model never writes it; it is built from accepted, verified metric claims. */
export const answerChartSchema = z.object({
  currency: z.string().regex(/^[A-Z]{3}$/),
  rows: z.array(z.object({
    label: z.string().min(1).max(240),
    valueMinor: z.string().regex(/^-?(?:0|[1-9]\d{0,79})$/),
    href: z.string().max(500).regex(/^\/money\/transactions\?[\w=&%.-]*$/).optional(),
  }).strict()).min(2).max(20),
}).strict();
export type AnswerChart = z.infer<typeof answerChartSchema>;
type AcceptedClaim = { operation: string; operands: { receiptId: string; metricId: string }[]; valueMinor: string; currency: string; unit: string };

const uuid = z.uuid();

/** Filtered transactions for a metric: its period, plus direction and account when the evidence names them. */
function transactionsHref(metric: EvidenceReceipt["metrics"][number], receipt: EvidenceReceipt) {
  const params = new URLSearchParams({ from: metric.period.from, to: metric.period.to });
  if (/(^|\.)incomeMinor$/.test(metric.id)) params.set("direction", "income");
  if (/(^|\.)spendingMinor$/.test(metric.id)) params.set("direction", "outflow");
  const input = receipt.query.input;
  const account = input && typeof input === "object" && !Array.isArray(input) ? input.accountId : undefined;
  if (uuid.safeParse(account).success) params.set("account", account as string);
  return `/money/transactions?${params}`;
}

export function answerChart(accepted: AcceptedClaim[], receipts: EvidenceReceipt[], workspaceId: string): AnswerChart | null {
  const byCurrency = new Map<string, AnswerChart["rows"]>();
  for (const claim of accepted) {
    if (claim.operation !== "metric" || claim.unit !== "money" || claim.operands.length !== 1) continue;
    const receipt = receipts.find(item => item.id === claim.operands[0].receiptId && item.workspaceId === workspaceId);
    const metric = receipt?.metrics.find(item => item.id === claim.operands[0].metricId);
    if (!receipt || !metric || metric.valueMinor !== claim.valueMinor || metric.currency !== claim.currency) continue;
    const rows = byCurrency.get(claim.currency) ?? [];
    const label = `${metric.label} · ${metric.period.from === metric.period.to ? metric.period.from : `${metric.period.from} to ${metric.period.to}`}`;
    if (!rows.some(row => row.label === label)) rows.push({ label, valueMinor: claim.valueMinor, href: transactionsHref(metric, receipt) });
    byCurrency.set(claim.currency, rows);
  }
  const [currency, rows] = [...byCurrency].sort((a, b) => b[1].length - a[1].length)[0] ?? [];
  return currency && rows && rows.length >= 2 ? { currency, rows: rows.slice(0, 20) } : null;
}

/** Places the chart after the measured facts and before the evidence trail. */
export function withAnswerChart(body: string, chart: AnswerChart | null) {
  if (!chart) return body;
  const block = `\`\`\`moneo-chart\n${JSON.stringify(chart)}\n\`\`\``;
  const trail = body.lastIndexOf("\n\nEvidence trail\n\n");
  return trail < 0 ? `${body}\n\n${block}` : `${body.slice(0, trail)}\n\n${block}${body.slice(trail)}`;
}
import { z } from "zod";

export type FollowUp = { label: string; prompt?: string; href?: string };
export const planInput = z.object({
  steps: z.array(z.string().trim().min(3).max(120)).min(1).max(6),
  followUps: z.array(z.string().trim().min(3).max(120)).max(3).optional(),
}).strict();

const ANALYSIS = ["finance_investigate", "analytics_cashflow", "reviews_investigate", "finance_scenario"];
/**
 * Up to four next steps after an answer: the model's own follow-up questions
 * (text only, never actions) first, then deterministic app actions.
 */
export function chatFollowUps(message: string, toolsUsed: string[], modelPrompts: string[] = []): FollowUp[] {
  const items: FollowUp[] = modelPrompts.map(prompt => ({ label: prompt, prompt }));
  const analysed = toolsUsed.some(name => ANALYSIS.includes(name));
  if (analysed && !/merchant/i.test(message)) items.push({ label: "Break this down by merchant", prompt: `${message.slice(0, 200)} Break it down by merchant.` });
  if (analysed && !/last year|previous year/i.test(message)) items.push({ label: "Compare with the same period last year", prompt: `${message.slice(0, 200)} Compare with the same period last year.` });
  if (/\b(subscriptions?|recurring|bills?)\b/i.test(message)) items.push({ label: "Review recurring payments", href: "/money/recurring" });
  if (/\b(why|explain|what changed|unusual|anomal)/i.test(message) && !toolsUsed.includes("reviews_start")) items.push({ label: "Start a deep review", prompt: `Start a deep review: ${message.slice(0, 200)}` });
  items.push({ label: "Let the agent team dig deeper", href: "/ai/agents" });
  return [...new Map(items.map(item => [item.label.toLowerCase(), item])).values()].slice(0, 4);
}
export type ReportedUsage = { model_id: string; input_tokens: number | null; output_tokens: number | null; total_tokens: number | null };

export function reportedUsage(modelId: string, usage: { inputTokens?: number; outputTokens?: number; totalTokens?: number }): ReportedUsage {
  const count = (value: number | undefined) => Number.isSafeInteger(value) && value! >= 0 ? value! : null;
  return { model_id: modelId, input_tokens: count(usage.inputTokens), output_tokens: count(usage.outputTokens), total_tokens: count(usage.totalTokens) };
}

export function usageLabel(usage: ReportedUsage | null) {
  return usage ? `${usage.model_id} · input ${usage.input_tokens ?? "unknown"}, output ${usage.output_tokens ?? "unknown"}, total ${usage.total_tokens ?? "unknown"} tokens · cost unknown` : "Token usage and cost unknown";
}
